-- Catalog only. Run after installing the unchanged cumulative candidate in isolation.
SELECT jsonb_build_object(
 'version',current_setting('server_version'),
 'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'schema',n.nspname,'name',p.proname,'identity_arguments',pg_get_function_identity_arguments(p.oid),'arguments',pg_get_function_arguments(p.oid),'returns',pg_get_function_result(p.oid),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'settings',p.proconfig,'body',p.prosrc,'definition_sha_marker',md5(pg_get_functiondef(p.oid)),'acl',p.proacl::text,'public_execute',EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))x WHERE x.grantee=0 AND x.privilege_type='EXECUTE'),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'))ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('workspace_private','workspace_auth_bridge','workspace_bootstrap')OR(n.nspname='public'AND left(p.proname,3)='ws_')),
 'tables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text,'authenticated_select',has_table_privilege('authenticated',c.oid,'SELECT'),'authenticated_update',has_table_privilege('authenticated',c.oid,'UPDATE'))ORDER BY n.nspname,c.relname)FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN('workspace','workspace_private','workspace_auth_bridge','workspace_bootstrap')AND c.relkind='r'),
 'policies',(SELECT jsonb_agg(to_jsonb(p)ORDER BY schemaname,tablename,policyname)FROM pg_policies p WHERE schemaname IN('workspace','workspace_private','workspace_auth_bridge','workspace_bootstrap')),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid))ORDER BY c.conrelid::regclass::text,c.conname)FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname IN('workspace','workspace_private','workspace_auth_bridge','workspace_bootstrap')),
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'super',rolsuper,'login',rolcanlogin,'bypass',rolbypassrls,'create_role',rolcreaterole,'create_db',rolcreatedb,'replication',rolreplication))FROM pg_roles WHERE rolname IN('ws_owner','ws_runtime','ws_authz_reader','ws_bootstrap_executor','ws_bootstrap_operator','supabase_auth_admin')),
 'memberships',(SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(roleid),'member',pg_get_userbyid(member),'admin',admin_option,'inherit',inherit_option,'set',set_option))FROM pg_auth_members WHERE roleid IN(SELECT oid FROM pg_roles WHERE left(rolname,3)='ws_')OR member IN(SELECT oid FROM pg_roles WHERE left(rolname,3)='ws_')),
 'schema_acl',(SELECT jsonb_agg(jsonb_build_object('schema',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text))FROM pg_namespace WHERE nspname IN('workspace','workspace_private')),
 'auth_columns',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'reader_select',has_column_privilege('ws_authz_reader',c.oid,a.attnum,'SELECT'),'runtime_select',has_column_privilege('ws_runtime',c.oid,a.attnum,'SELECT')))FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid WHERE n.nspname='auth'AND c.relname IN('users','sessions')AND a.attnum>0 AND NOT a.attisdropped));
